INSERT OR REPLACE INTO cards (id, name, name_cn, name_jp, type, race, attribute, level, atk, def, desc_cn) VALUES
(90135989, 'Cloudian Squall', '云魔物的阵雨', '雲魔物のスコール', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '每次自己的准备阶段时给场上表侧表示存在的全部怪兽放置1个雾指示物。'),
(56597273, 'Cloudian Token', '云魔物-羊云', '雲魔物－羊雲', 'Token', 'Fairy', NULL, NULL, NULL, NULL, NULL),
(300302059, 'Cloudy Skies of Grey', NULL, NULL, 'Skill Card', 'Adrian Gecko', NULL, NULL, NULL, NULL, NULL),
(83232904, 'Clown Clan "Malabarism"', NULL, NULL, 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, NULL),
(57847269, 'Clown Clan "Matinee"', NULL, NULL, 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, NULL),
(6547248, 'Clown Clan "New Face"', NULL, NULL, 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, NULL),
