(91237821, 'Clown Clan Devils', NULL, NULL, 'XYZ Monster', 'Beast-Warrior', 'LIGHT', 3, NULL, 2000, NULL),
(31533473, 'Clown Clan Diablo', NULL, NULL, 'Fusion Monster', 'Beast-Warrior', 'LIGHT', 5, 200, 1800, NULL),
(42759961, 'Clown Clan Flair', NULL, NULL, 'Ritual Effect Monster', 'Beast-Warrior', 'LIGHT', 1, 500, 1000, NULL),
(93172951, 'Clown Clan Meteor', NULL, NULL, 'Synchro Monster', 'Beast-Warrior', 'LIGHT', 6, 600, 1300, NULL),
(82159583, 'Clown Clan Whiteface', NULL, NULL, 'Effect Monster', 'Illusion', 'LIGHT', 7, 2500, 2500, NULL),
(92667214, 'Clown Zombie', '杀人小丑僵尸', 'マーダーサーカス・ゾンビ', 'Normal Monster', 'Zombie', 'DARK', 2, 1350, NULL, '使用黑暗力量重生的小丑，利用摇晃的舞蹈将对方引向死亡。'),
(94703021, 'Cluster Congester', '集群拥塞器', 'クラスター・コンジェスター', 'Effect Monster', 'Cyberse', 'LIGHT', 7, 1000, 2200, '这个卡名的①的效果1回合只能使用1次。 ①：自己场上没有连接怪兽存在，这张卡召唤·特殊召唤成功的场合才能发动。在自己场上把1只「拥塞器衍生物」（电子界族·暗·1星·攻/守0）特殊召唤。 ②：自己的连接怪兽被攻击的战斗步骤1次，把那只连接怪兽和墓地的这张卡除外才能发动。把最多有对方场上的连接怪兽数量的「拥塞器衍生物」在自己场上特殊召唤。'),
(67136033, 'Coach Captain Bearman', '热血兽王 熊人', '熱血獣王ベアーマン', 'Effect Monster', 'Beast-Warrior', 'FIRE', 8, 2600, 2700, '把这张卡作为超量召唤的素材的场合，不是战士族·炎属性怪兽的超量召唤不能使用。 ①：这张卡可以不用解放作召唤。这个方法召唤的这张卡的原本攻击力变成1300。 ②：1回合1次，自己主要阶段才能发动。自己场上的全部兽战士族·4星怪兽的等级直到回合结束时变成8星。'),
(42541548, 'Coach Goblin', '鬼哥布林', '鬼ゴブリン', 'Effect Monster', 'Fiend', 'EARTH', 4, 1200, 1500, '只要这张卡在自己场上以表侧表示存在，在自己回合的结束阶段时，可以将1张通常怪兽卡从手卡放回卡组最下方，再从卡组抽1张卡。此效果每回合只能使用1次。'),
(30741334, 'Coach King Giantrainer', '热血指导王 巨人训练师', '熱血指導王ジャイアントレーナー', 'XYZ Monster', 'Warrior', 'FIRE', 8, 2800, 2000, '8星怪兽×3 这个卡名的效果1回合可以使用最多3次，这个效果发动的回合，自己不能进行战斗阶段。 ①：把这张卡1个超量素材取除才能发动。自己抽1张，给双方确认。那是怪兽的场合，再给与对方800伤害。'),
(3534077, 'Coach Soldier Wolfbark', '热血兽士 狼嚎', '熱血獣士ウルフバーク', 'Effect Monster', 'Beast-Warrior', 'FIRE', 4, 1600, 1200, '这个卡名的效果1回合只能使用1次。 ①：以自己墓地1只兽战士族·炎属性·4星怪兽为对象才能发动。那只怪兽守备表示特殊召唤。这个效果特殊召唤的怪兽的效果无效化。'),
(86801871, 'Cobra Jar', '蛇壶', 'スネークポット', 'Flip Effect Monster', 'Reptile', 'EARTH', 2, 600, 300, '反转：在自己场上把1只「毒蛇衍生物」（爬虫类族·地·3星·攻/守1200）特殊召唤。「毒蛇衍生物」被战斗破坏的场合，给与对方基本分500分伤害。'),
(75109441, 'Cobraman Sakuzy', '半蛇人 萨库兹', '半蛇人サクズィー', 'Effect Monster', 'Reptile', 'EARTH', 3, 800, 1400, '这张卡1回合只有1次可以变成里侧守备表示。这张卡反转时，对方场上盖放的魔法·陷阱卡全部翻开，确认后回复原状。'),
(94395649, 'Cocatorium the Heavy Metal Avian', '超重禽属 鸡蛇矿', '超重禽属コカトリウム', 'Effect Monster', 'Winged Beast', 'WIND', 4, 1300, 900, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡在手卡·墓地存在的场合，把自己场上1只兽族·兽战士族·鸟兽族怪兽解放才能发动。这张卡特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。 ②：从卡组把1只4星以下的兽族·兽战士族·鸟兽族怪兽除外才能发动。直到结束阶段，这张卡当作和除外的怪兽同名卡使用，变成相同种族·属性·等级。'),
(42338879, 'Cockadoodledoo', '喔喔公鸡', 'こけコッコ', 'Tuner Monster', 'Winged Beast', 'WIND', 5, 1600, 2000, '①：双方场上没有怪兽存在的场合，这张卡可以作为3星怪兽从手卡特殊召唤。 ②：对方场上有怪兽存在，自己场上没有卡存在的场合，这张卡可以作为4星怪兽从手卡特殊召唤。 ③：表侧表示的这张卡从场上离开的场合除外。'),
(33413638, 'Cockroach Knight', '蟑螂骑士', 'コカローチ・ナイト', 'Effect Monster', 'Insect', 'EARTH', 3, 800, 900, '这张卡送去墓地时，这张卡回到卡组最上面。'),
(40240595, 'Cocoon of Evolution', '进化之茧', '進化の繭', 'Effect Monster', 'Insect', 'EARTH', 3, NULL, 2000, '这张卡可以从手卡当作装备卡使用给场上表侧表示存在的「飞蛾宝宝」装备。用这个效果把这张卡装备的「飞蛾宝宝」的攻击力·守备力按「进化之茧」的数值适用。'),
(77840540, 'Cocoon of Ultra Evolution', '超进化之茧', '超進化の繭', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：有装备卡装备的自己·对方场上1只昆虫族怪兽解放，从卡组把1只昆虫族怪兽无视召唤条件特殊召唤。 ②：自己主要阶段把墓地的这张卡除外，以自己墓地1只昆虫族怪兽为对象才能发动。那只怪兽回到卡组洗切。那之后，自己从卡组抽1张。'),
(300104004, 'Cocoon of Ultra Evolution (Skill Card)', NULL, NULL, 'Skill Card', 'Weevil', NULL, NULL, NULL, NULL, NULL),
(80368942, 'Cocoon Party', '茧状体派对', 'コクーン・パーティ', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '自己墓地存在的名字带有「新空间侠」的怪兽每有1种类，把1只名字带有「茧状体」的怪兽从自己卡组特殊召唤。'),
(43644025, 'Cocoon Rebirth', '茧状体再生', 'コクーン・リボーン', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '可以把自己场上表侧表示存在的1只名字带有「茧状体」的怪兽作为祭品，那张卡记述的1只名字带有「新空间侠」的怪兽从墓地特殊召唤。'),
(56641453, 'Cocoon Veil', '茧状衣', 'コクーン・ヴェール', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '把自己场上表侧表示存在的1只名字带有「茧状体」的怪兽作为祭品才能发动。这个回合效果的对玩家的伤害变成0。之后，作为祭品的名字带有「茧状体」的怪兽记述的1只名字带有「新空间侠」的怪兽从手卡·卡组·墓地特殊召唤。'),
(65496056, 'Codarus', '科达路斯', 'コダロス', 'Effect Monster', 'Sea Serpent', 'WATER', 4, 1400, 1200, '把自己场上表侧表示存在的「海」送去墓地才能发动。选择对方场上最多2张卡送去墓地。'),
(99342953, 'Code A Ancient Ruins', '古代遗迹 代号A', '古代遺跡コードA', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '每次场上表侧表示存在的名字带有「外星」的怪兽被破坏，给这张卡放置1个A指示物。1回合1次，可以把场上存在的2个A指示物取除，自己墓地存在的1只名字带有「外星」的怪兽特殊召唤。'),
(37119142, 'Code Exporter', '码输出者', 'コード・エクスポーター', 'Effect Monster', 'Cyberse', 'WIND', 5, 500, 2300, '这个卡名的①②的效果1回合各能使用1次。 ①：把自己场上的电子界族怪兽作为「码语者」怪兽的连接素材的场合，手卡的这张卡也能作为连接素材。 ②：这张卡作为「码语者」怪兽的连接素材从手卡·场上送去墓地的场合，以自己墓地1只4星以下的电子界族怪兽为对象才能发动。那只怪兽加入手卡。场上的这张卡为素材的场合可以不加入手卡把效果无效特殊召唤。'),
(30114823, 'Code Generator', '码生成者', 'コード・ジェネレーター', 'Effect Monster', 'Cyberse', 'EARTH', 3, 1300, 500, '这个卡名的①②的效果1回合各能使用1次。 ①：把自己场上的电子界族怪兽作为「码语者」怪兽的连接素材的场合，手卡的这张卡也能作为连接素材。 ②：这张卡作为「码语者」怪兽的连接素材从手卡·场上送去墓地的场合才能发动。从卡组把1只攻击力1200以下的电子界族怪兽送去墓地。场上的这张卡为素材的场合也能不送去墓地加入手卡。'),
(33750856, 'Code Hack', '代码骇入', 'コード・ハック', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：自己场上的电子界族连接怪兽不会被对方的效果破坏。 ②：1回合1次，自己和对方的怪兽之间进行战斗的战斗步骤才能发动。那只对方怪兽的攻击力直到回合结束时变成0，双方怪兽不会被那次战斗破坏，那次战斗发生的双方的战斗伤害变成0。 ③：自己的「码语者」怪兽攻击的伤害步骤对方把效果发动时，把墓地的这张卡除外才能发动。那个发动无效，那只攻击怪兽的攻击力上升700。'),
(5088741, 'Code Igniter', '码引燃者', 'コード・イグナイター', 'XYZ Monster', 'Cyberse', 'DARK', 4, 2300, 2000, '4星怪兽×2 这个卡名的①②③的效果1回合各能使用1次。 ①：这张卡超量召唤的场合才能发动。从卡组把1只电子界族仪式怪兽加入手卡。 ②：把这张卡1个超量素材取除才能发动。等级合计直到变成仪式召唤的怪兽的等级以上为止，把自己的手卡·场上的怪兽解放，从手卡把1只仪式怪兽仪式召唤。 ③：这张卡作为连接素材送去墓地的场合才能发动。从卡组把1张「“艾”」陷阱卡加入手卡。'),
(74652966, 'Code of Soul', '魂之代码', 'コード・オブ・ソウル', 'Effect Monster', 'Cyberse', 'FIRE', 3, 500, 500, '这个卡名的①②③的效果1回合各能使用1次。 ①：自己场上有连接怪兽存在的场合才能发动。这张卡从手卡特殊召唤。 ②：自己主要阶段才能发动。这个回合，自己要把「转生炎兽」连接怪兽连接召唤的场合1次，可以只用自己场上1只同名「转生炎兽」连接怪兽为素材作连接召唤。 ③：对方主要阶段，把墓地的这张卡除外才能发动。进行1只连接3以上的电子界族连接怪兽的连接召唤。'),
(75130221, 'Code Radiator', '码冷却者', 'コード・ラジエーター', 'Effect Monster', 'Cyberse', 'WATER', 4, 1600, 800, '这个卡名的①②的效果1回合各能使用1次。 ①：把自己场上的电子界族怪兽作为「码语者」怪兽的连接素材的场合，手卡的这张卡也能作为连接素材。 ②：这张卡作为「码语者」怪兽的连接素材从手卡·场上送去墓地的场合，以对方场上1只表侧表示怪兽为对象才能发动。那只怪兽攻击力变成0，效果无效化。场上的这张卡为素材的场合这个效果的对象可以变成2只。'),
(53413628, 'Code Talker', '码语者', 'コード・トーカー', 'Link Monster', 'Cyberse', 'DARK', NULL, 1300, NULL, '效果怪兽2只 ①：这张卡的攻击力上升这张卡所连接区的怪兽数量×500。 ②：只要这张卡所连接区有怪兽存在，这张卡不会被战斗以及对方的效果破坏。'),
(45462149, 'Code Talker Inverted', '码语者・倒置', 'コード・トーカー・インヴァート', 'Link Monster', 'Cyberse', 'LIGHT', NULL, 1300, NULL, '电子界族怪兽2只 这个卡名的效果1回合只能使用1次。 ①：这张卡连接召唤成功的场合才能发动。从手卡把1只电子界族怪兽在作为这张卡所连接区的自己场上特殊召唤。'),
(48736598, 'Codebreaker Virus Berserker', '码破者・病毒狂战士', 'コードブレイカー・ウイルスバーサーカー', 'Link Monster', 'Warrior', 'DARK', NULL, 2800, NULL, '包含「代码破坏者」怪兽的怪兽2只以上 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡特殊召唤成功时，这张卡是互相连接状态的场合才能发动。从自己的手卡·墓地选最多2只「代码破坏者」怪兽在作为连接怪兽所连接区的自己·对方场上特殊召唤。 ②：自己主要阶段才能发动。选最多有自己·对方场上的连接状态的「代码破坏者」怪兽数量的对方场上的魔法·陷阱卡破坏。'),
(84121193, 'Codebreaker Virus Swordsman', '码破者・病毒剑客', 'コードブレイカー・ウイルスソードマン', 'Link Monster', 'Warrior', 'DARK', NULL, 2300, NULL, '效果怪兽2只 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡特殊召唤成功时，这张卡是互相连接状态的场合才能发动。从自己的手卡·卡组·墓地选1只「代码破坏者·零日」在作为连接怪兽所连接区的自己·对方场上特殊召唤。 ②：这张卡被对方破坏送去墓地的回合的结束阶段才能发动。这张卡特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。'),
(8662794, 'Codebreaker Zero Day', '码破者・零日', 'コードブレイカー・ゼロデイ', 'Effect Monster', 'Warrior', 'DARK', 4, 1800, NULL, '①：「代码破坏者」连接怪兽以外的和这张卡连接状态的连接怪兽的攻击力下降1000。 ②：这张卡已在怪兽区域存在的状态，场上的「代码破坏者」连接怪兽被战斗·效果破坏的场合发动。这张卡破坏。 ③：这张卡被战斗·效果破坏的场合才能发动。从卡组把1只「代码破坏者·零日」加入手卡。'),
(65830223, 'Coffin Seller', '卖棺者', '棺桶売り', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '每次对方的怪兽卡送去墓地，对方基本分受到300分的伤害。'),
(24661486, 'Cold Enchanter', '冰寒魔法师', 'コールド・エンチャンター', 'Effect Monster', 'Aqua', 'WATER', 4, 1600, 1200, '丢弃1张手卡才能发动。选择场上表侧表示存在的1只怪兽放置1个冰指示物。只要这张卡在场上表侧表示存在，这张卡的攻击力上升场上的冰指示物数量×300的数值。'),
(40383551, 'Cold Feet', '大寒气', '大寒気', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个回合，自己不能作魔法·陷阱卡的效果使用以及发动·盖放。'),
(60682203, 'Cold Wave', '大寒波', '大寒波', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '主要阶段1的开始时才能发动。直到下次的自己的抽卡阶段时，双方不能有魔法·陷阱卡的效果使用以及发动·盖放。'),
(300302060, 'Cold-Blooded Tactician', NULL, NULL, 'Skill Card', 'Thelonious Vi', NULL, NULL, NULL, NULL, NULL),
(7565547, 'Collected Power', '力之集约', '力の集約', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '选择场上表侧表示存在的1只怪兽发动。场上存在的全部装备卡给选择的怪兽装备。对象不正确的装备卡破坏。'),
(54656181, 'Colonel on C-String', 'C战场的指挥官 上校', 'C戦場の指揮官 コロネル', 'Effect Monster', 'Warrior', 'LIGHT', 4, 1400, 1600, '①：这张卡召唤成功时才能发动。从手卡把2只4星以下的战士族怪兽守备表示特殊召唤（同名卡最多1张）。'),
(23693634, 'Colossal Fighter', '巨人斗士', 'ギガンテック・ファイター', 'Synchro Monster', 'Warrior', 'DARK', 8, 2800, 1000, '调整＋调整以外的怪兽1只以上 这张卡的攻击力上升双方墓地的战士族怪兽数量×100的数值。这张卡被战斗破坏送去墓地时，可以选择自己或者对方的墓地1只战士族怪兽在自己场上特殊召唤。'),
(38898779, 'Colossal Fighter/Assault Mode', '巨人斗士／爆裂', 'ギガンテック・ファイター／バスター', 'Effect Monster', 'Warrior', 'DARK', 10, 3300, 1500, '这张卡不能通常召唤。「爆裂模式」的效果才能特殊召唤。只要这张卡在场上表侧表示存在，全部对方怪兽的攻击力下降自己墓地存在的战士族怪兽数量×100的数值。这张卡特殊召唤成功时，可以从自己卡组选择最多2只战士族怪兽送去墓地。此外，场上存在的这张卡被破坏时，可以把自己墓地存在的1只「巨人斗士」特殊召唤。'),
(52518793, 'Colosseum - Cage of the Gladiator Beasts', '剑斗兽之槛-圆形斗技场', '剣闘獣の檻－コロッセウム', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '每次怪兽从卡组在场上特殊召唤，给这张卡放置1个指示物。场上表侧表示存在的名字带有「剑斗兽」的怪兽，这张卡每放置有1个指示物，攻击力·守备力上升100。这张卡被卡的效果破坏时，可以从手卡丢弃1张「剑斗兽之槛-圆形斗技场」让这张卡不破坏。'),
(37480144, 'Column Switch', '瞬间转移', 'アスポート', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：以自己的主要怪兽区域1只怪兽为对象才能发动。那只自己怪兽的位置向其他的自己的主要怪兽区域移动。'),
(12501230, 'Combat Wheel', '战斗车轮', 'コンバット・ホイール', 'Synchro Monster', 'Machine', 'EARTH', 6, 2500, 1200, '调整＋调整以外的怪兽1只以上 ①：场上的这张卡1回合只有1次不会被对方的效果破坏。 ②：对方战斗阶段1次，丢弃1张手卡才能发动。这张卡的攻击力上升自己场上的其他怪兽的攻击力合计数值的一半。那之后，给这张卡放置1个指示物。这个回合中，对方怪兽不能选择其他怪兽作为攻击对象。 ③：有指示物放置的这张卡被战斗破坏的场合发动。自己场上的怪兽全部破坏。'),
(8964854, 'Combination Attack', '联合攻击', 'コンビネーション・アタック', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '有同盟怪兽装备的怪兽进行过战斗的战斗阶段时才能发动。选择1只有同盟怪兽装备并进行过战斗的怪兽，把装备的同盟解除。选择的怪兽在这个回合可以再1次攻击。'),
(17217034, 'Combined Maneuver - Engage Zero!', '合体术式－交闪零式', '合体術式－エンゲージ・ゼロ', 'Link Monster', 'Machine', 'LIGHT', NULL, 1500, NULL, '光·暗属性怪兽2只 这个卡名在规则上也当作「闪刀姬」卡使用。自己对「合体术式-交闪零式」1回合只能有1次特殊召唤，这张卡不能作为连接素材。 ①：这张卡特殊召唤的场合，以场上1只攻击力2500以上的怪兽为对象才能发动。那只怪兽的效果直到回合结束时无效。 ②：自己墓地有「闪刀姬-零衣」以及「闪刀姬-露世」存在的场合，这张卡攻击的伤害步骤开始时才能发动。对方场上的怪兽全部破坏。'),
(8806072, 'Combo Fighter', '连击战士', 'コンボファイター', 'Effect Monster', 'Warrior', 'WIND', 4, 1600, 800, '这张卡在场上表侧表示存在时自己回合的主要阶段一有连锁发生的场合，只在这个回合这张卡可以在同1次战斗阶段作2次攻击。'),
(44800181, 'Combo Master', '连击大师', 'コンボマスター', 'Effect Monster', 'Warrior', 'WIND', 5, 2200, 1500, '这张卡在场上表侧表示存在时自己回合的主要阶段一有连锁发生的场合，只在这个回合这张卡可以在同1次战斗阶段作2次攻击。'),
(33453260, 'Comic Hand', '漫画之手', 'コミックハンド', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '自己场上有「卡通世界」存在的场合才能给对方场上的怪兽装备。 ①：得到装备怪兽的控制权。 ②：装备怪兽也当作卡通怪兽使用，对方场上没有卡通怪兽存在的场合，装备怪兽可以直接攻击。 ③：场上没有「卡通世界」存在的场合这张卡破坏。'),
(77631175, 'Comics Hero King Arthur', '漫画英雄 亚瑟王', 'CHキング・アーサー', 'XYZ Monster', 'Warrior', 'EARTH', 4, 2400, 1200, '战士族4星怪兽×2 这张卡被战斗破坏的场合，可以作为代替把这张卡1个超量素材取除。这个效果让超量素材被取除时，这张卡的攻击力上升500，给与对方基本分500分伤害。'),
(10375182, 'Command Knight', '指挥骑士', 'コマンド・ナイト', 'Effect Monster', 'Warrior', 'FIRE', 4, 1200, 1900, '①：只要这张卡在怪兽区域存在，自己场上的战士族怪兽的攻击力上升400。 ②：只要自己场上有其他怪兽存在，对方不能选择这张卡作为攻击对象。'),
(78184733, 'Command Performance', '娱乐一闪', 'エンタメ・フラッシュ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己场上有「娱乐伙伴」怪兽存在的场合才能发动。对方场上的表侧攻击表示怪兽全部变成守备表示，那些怪兽直到下个回合的结束时不能把表示形式变更。'),
(22666164, 'Commander Covington', '督战官 科温顿', '督戦官コヴィントン', 'Effect Monster', 'Machine', 'EARTH', 4, 1000, 600, '①：把自己场上的表侧表示的「机甲士兵」「机甲狙击兵」「机甲卫兵」各1只送去墓地才能发动。从手卡·卡组把1只「机甲部队·武装力量」特殊召唤。'),
(53388413, 'Commander Gottoms, Swordmaster', '总剑司令 加特姆士', '総剣司令 ガトムズ', 'Effect Monster', 'Beast-Warrior', 'EARTH', 6, 2100, 1600, '只要这张卡在场上表侧表示存在，自己场上表侧表示存在的名字带有「剑士」的怪兽的攻击力上升400。'),
(12197543, 'Commander of Swords', '剑之指挥', '剣の采配', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '对方的抽卡阶段时，对方通常抽卡时才能发动。抽到的卡给双方确认，确认的卡是魔法·陷阱卡的场合，从以下效果选择1个适用。 ●把抽到的卡丢弃。 ●选对方场上1张魔法·陷阱卡破坏。'),
(72867001, 'Commander Souza, Swordmaster', '总剑司令 索扎', '総剣司令 ソウザ', 'Synchro Monster', 'Warrior', 'EARTH', 10, 2500, 1600, '调整＋地属性怪兽1只以上 这个卡名在规则上也当作「X-剑士」卡使用。 ①：这张卡的攻击力上升除外状态的怪兽数量×200。 ②：这张卡战斗破坏怪兽时才能发动。自己抽1张。 ③：1回合1次，对方把效果发动时，把自己场上1只「X-剑士」怪兽解放才能发动。对方场上1张卡破坏。 ④：这张卡被战斗·效果破坏的场合，可以作为代替把自己墓地1张「剑士」卡除外。'),
(43417563, 'Commencement Dance', '诱发之舞', '踊りによる誘発', 'Spell Card', 'Ritual', NULL, NULL, NULL, NULL, '「舞蹈战士」的降临必需。若不从场地和手卡把等级直到6以上的卡作为祭品，则「舞蹈战士」不能降临。'),
(40465719, 'Common Charity', '凡人的施舍', '凡人の施し', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '从卡组抽2张卡，之后从手卡把1张通常怪兽卡从游戏中除外。手卡没有通常怪兽卡的场合，手卡全部送去墓地。'),
(14772491, 'Common Soul', '魂之共有', '魂の共有－コモンソウル', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '选择场上表侧表示存在的1只怪兽发动。自己手卡的1只名字带有「新空间侠」的怪兽在选择怪兽的控制者的场上特殊召唤。选择怪兽的攻击力上升这个效果特殊召唤的名字带有「新空间侠」的怪兽的攻击力数值。这张卡从场上离开时，这张卡的效果特殊召唤的1只名字带有「新空间侠」的怪兽回到手卡。'),
(27450401, 'Compass Token', '密集钟摆', 'クラスター・ペンデュラム', 'Token', 'Machine', NULL, NULL, NULL, NULL, NULL),
(48216773, 'Compulsory Escape Device', '强制退出装置', '強制退出装置', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '双方各自选自己场上1只怪兽，那些怪兽回到持有者卡组。'),
(94192409, 'Compulsory Evacuation Device', '强制脱出装置', '強制脱出装置', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：以场上1只怪兽为对象才能发动。那只怪兽回到手卡。'),
(83602069, 'Comrade Swordsman of Landstar', '共同战斗的地星剑士', '共闘するランドスターの剣士', 'Tuner Monster', 'Warrior', 'EARTH', 3, 500, 1200, '只要这张卡在场上表侧表示存在，自己场上表侧表示存在的战士族怪兽的攻击力上升400。'),
(79627627, 'Conbirdable', '半缠鸟官－翻飞鸟', '半纏鳥官－コンバード', 'Flip Effect Monster', 'Winged Beast', 'EARTH', 8, 1400, 2800, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡在手卡存在的场合，自己·对方的战斗阶段，以场上1只里侧表示怪兽为对象才能发动。那只怪兽送去墓地，这张卡里侧守备表示特殊召唤。 ②：这张卡反转的场合才能发动。除「半缠鸟官-转变鸟」外的1只5星以上的反转怪兽从卡组里侧守备表示特殊召唤。'),
(20501450, 'Concentrating Current', '插座集中', 'コンセントレイト', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：以自己场上1只表侧表示怪兽为对象才能发动。那只怪兽的攻击力直到回合结束时上升那个守备力数值。这张卡发动的回合，作为对象的怪兽以外的自己怪兽不能攻击。'),
(14283055, 'Concours de Cuisine (Culinary Confrontation)', 'Concours de Cuisine～糕冷料理对决～', 'Concours de Cuisine～菓冷なる料理対決～', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：从手卡·卡组·额外卡组选1只「新式魔厨」灵摆怪兽和1只「圣菓使」灵摆怪兽在双方场上各1只特殊召唤。这个回合，自己不是「新式魔厨」怪兽以及「圣菓使」怪兽不能作为融合·同调·超量·连接召唤的素材。 ②：自己主要阶段把墓地的这张卡除外，以场上1只表侧表示怪兽为对象才能发动。那只怪兽的攻击力上升双方墓地的「食谱」卡数量×200。'),
(35306215, 'Condemned Darklord', '失乐的堕天使', '失楽の堕天使', 'Link Monster', 'Fairy', 'DARK', NULL, 1600, NULL, '天使族怪兽2只 这个卡名的②的效果1回合只能使用1次。 ①：只要这张卡在怪兽区域存在，自己作需要怪兽2只解放的天使族怪兽的上级召唤的场合，可以不把怪兽2只解放而从自己墓地把2只怪兽除外来上级召唤。 ②：丢弃1张手卡才能发动。从卡组选1只「堕天使」怪兽加入手卡或送去墓地。 ③：自己结束阶段发动。自己回复场上的天使族怪兽数量×500基本分。'),
(68018709, 'Condemned Maiden', '失乐圣女', '失楽の聖女', 'Effect Monster', 'Fairy', 'LIGHT', 4, 100, 2000, '这个卡名的效果在决斗中只能使用1次。 ①：只要这张卡在怪兽区域存在，自己在对方回合可以把1张速攻魔法卡从手卡发动。'),
(44656450, 'Condemned Witch', '失乐魔女', '失楽の魔女', 'Effect Monster', 'Fairy', 'DARK', 4, 100, 2000, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤成功时才能发动。从卡组把1张「禁忌的」速攻魔法卡加入手卡。 ②：对方主要阶段，把这张卡解放才能发动。从卡组把「失乐之魔女」以外的1只天使族·4星怪兽特殊召唤。'),
(57093995, 'Condolence Puppet', '哀悼傀偶', 'コンドーレンス・パペット', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：把最多有从额外卡组特殊召唤的对方场上的怪兽数量＋1张的「机关傀儡」怪兽从卡组送去墓地（同名卡最多1张）。 ②：把墓地的这张卡除外，以自己场上1只机械族超量怪兽为对象才能发动。那只怪兽只要在场上表侧表示存在，不会被对方的效果破坏。'),
(44839512, 'Conduction Warrior Linear Magnum Plus Minus', '超电导战士 线性麦格农±', '超電導戦士 リニア・マグナム±', 'Effect Monster', 'Rock', 'EARTH', 7, 2700, 1300, '这张卡不能通常召唤。「超电导战士 线性磁炮王±」1回合1次在从自己的手卡·卡组·场上（表侧表示）把2只原本等级是4星以下的「磁石战士」怪兽送去墓地的场合可以特殊召唤。这个卡名的①②的效果1回合各能使用1次。 ①：以场上1只其他的地属性怪兽为对象才能发动。这张卡的攻击力直到回合结束时上升那个攻击力一半数值。 ②：这张卡被破坏送去墓地的场合发动。这张卡加入手卡。'),
(47247792, 'Conduction Warrior Plasma Magnum', '超电导战骑 等离子麦格农', '超電導戦騎プラズマ・マグナム', 'Fusion Monster', 'Rock', 'EARTH', 7, 2300, 2800, '岩石族·地属性怪兽×2 这个卡名的①③的效果1回合各能使用1次。 ①：这张卡融合召唤的场合才能发动。从卡组把1张「磁力」通常·速攻·场地魔法卡加入手卡。 ②：只要这张卡在怪兽区域存在，场上的表侧表示怪兽变成地属性。 ③：从卡组把1只8星「磁石战士」怪兽送去墓地才能发动。进行1只4星以下的「磁石战士」怪兽的召唤。'),
(8454126, 'Conductor of Nephthys', '奈芙蒂斯的连系者', 'ネフティスの繋ぎ手', 'Ritual Effect Monster', 'Spellcaster', 'WIND', 2, 2000, NULL, '「奈芙提斯的轮回」降临。这个卡名的①②的效果1回合各能使用1次。 ①：这张卡仪式召唤成功的场合才能发动。从手卡·卡组把「奈芙提斯之联结者」以外的1只「奈芙提斯」仪式怪兽当作仪式召唤作特殊召唤。 ②：这张卡被「奈芙提斯」卡的效果所解放的场合或者所破坏的场合才能发动。下次的准备阶段，从自己的手卡·卡组·场上各选最多1张仪式怪兽以外的「奈芙提斯」卡破坏。'),
(53618197, 'Confiras de Nouvelles', '油封之康菲拉斯・饿魔新飨', 'コンフィラス・ド・ヌーベルズ', 'Ritual Effect Monster', 'Warrior', 'DARK', 2, 800, 1850, '「食谱」卡降临。这个卡名的①②的效果1回合各能使用1次。 ①：这张卡特殊召唤成功的场合，以场上1张魔法·陷阱卡为对象才能发动。那张卡破坏。 ②：场上的这张卡成为攻击·效果的对象时才能发动。这张卡和自己·对方场上1只攻击表示怪兽解放，从手卡·卡组把1只3·4星的「新式魔厨」仪式怪兽特殊召唤。'),
(17375316, 'Confiscation', '收押', '押収', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '支付1000基本分发动。把对方手卡确认，从那之中选1张卡丢弃。'),
(15721123, 'Confronting the "C"', '对峙的G', '対峙するG', 'Effect Monster', 'Insect', 'EARTH', 5, 1100, 2500, '①：对方从额外卡组把怪兽特殊召唤时才能发动。这张卡从手卡特殊召唤。这个效果特殊召唤的这张卡不受以这张卡为对象的怪兽的效果影响。'),
(67630339, 'Confusion Chaff', '混乱箔片', 'コンフュージョン・チャフ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '同1次的战斗阶段中宣言第2次的直接攻击时才能发动。那只对方怪兽和直接攻击过的第1只对方怪兽战斗进行伤害计算。'),
(20590515, 'Conquistador of the Golden Land', '黄金乡兵卒', '黄金郷のコンキスタドール', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：这张卡发动后变成通常怪兽（不死族·光·5星·攻500/守1800）在怪兽区域特殊召唤（也当作陷阱卡使用）。自己场上有「黄金卿 黄金国巫妖」存在的场合，可以再把场上1张表侧表示卡破坏。 ②：自己·对方的结束阶段，把墓地的这张卡除外才能发动。从卡组把1张「黄金国永生药」魔法·陷阱卡在自己场上盖放。'),
(31000575, 'Conscription', '征兵令', '徴兵令', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '检视对方卡组最上面的1张卡，如果那张卡是可以通常召唤的怪兽的场合，在自己场上特殊召唤。是其他卡的场合，那张卡加到对方的手卡。'),
(2980764, 'Consecrated Light', '神圣之灯', '聖なるあかり', 'Effect Monster', 'Fairy', 'LIGHT', 1, NULL, NULL, '这张卡不会被和暗属性怪兽的战斗破坏，那次战斗发生的对自己的战斗伤害变成0。只要这张卡在场上表侧表示存在，暗属性怪兽不能攻击宣言，双方不能把暗属性怪兽召唤·特殊召唤。'),
(63413494, 'Consolation Prize', '废车复活', '廃車復活', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从自己或者对方的手卡有怪兽被送去墓地的场合，以那1只怪兽为对象才能发动。那只怪兽在自己场上特殊召唤。'),
(43513897, 'Constellar Acubens', '星圣·柳宿增三', 'セイクリッド・アクベス', 'Effect Monster', 'Machine', 'LIGHT', 4, 800, 2000, '这张卡召唤·特殊召唤成功时，自己场上的全部名字带有「星圣」的怪兽的攻击力上升500。'),
(15871676, 'Constellar Aldebaran', '星圣·毕宿五', 'セイクリッド・ダバラン', 'Effect Monster', 'Beast-Warrior', 'LIGHT', 3, 1300, 800, '这张卡召唤成功时，可以从手卡把1只名字带有「星圣」的3星怪兽特殊召唤。'),
(41269771, 'Constellar Algiedi', '星圣 摩羯格雷迪', 'セイクリッド・グレディ', 'Effect Monster', 'Spellcaster', 'LIGHT', 4, 1600, 1400, '①：这张卡召唤成功时才能发动。从手卡把1只4星「星圣」怪兽特殊召唤。'),
(16906241, 'Constellar Alrescha', '星圣·外屏七', 'セイクリッド・レスカ', 'Effect Monster', 'Warrior', 'LIGHT', 6, 2200, 1200, '这张卡召唤成功时，可以从手卡把1只名字带有「星圣」的怪兽表侧守备表示特殊召唤。'),
(42391240, 'Constellar Antares', '星圣·心宿二', 'セイクリッド・アンタレス', 'Effect Monster', 'Machine', 'LIGHT', 6, 2400, 900, '这张卡召唤·特殊召唤成功时，可以选择自己墓地1只名字带有「星圣」的怪兽加入手卡。'),
(86825483, 'Constellar Belt', '神星领域', '神星なる領域', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '只要这张卡在场上存在，光属性怪兽的效果的发动不会被无效化。'),
(82913020, 'Constellar Caduceus', '星圣 卡多克乌斯', 'セイクリッド・カドケウス', 'Effect Monster', 'Spellcaster', 'LIGHT', 4, 1600, 1550, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上有「星圣商神杖使」以外的「星圣」怪兽存在的场合才能发动。这张卡从手卡特殊召唤。 ②：自己主要阶段才能发动。从卡组把1张「星圣」魔法·陷阱卡加入手卡。 ③：有这张卡在作为超量素材中的「星圣」超量怪兽得到以下效果。 ●这张卡和光·暗属性怪兽进行战斗的伤害计算前才能发动。那只怪兽除外。'),
(33302589, 'Constellar Castor', '星圣 双子卡斯托尔', 'セイクリッド・カストル', 'Effect Monster', 'Fairy', 'LIGHT', 4, 1700, 600, '这个卡名的①的效果1回合只能使用1次。 ①：这张卡召唤·反转召唤·特殊召唤的场合才能发动。从卡组把「星圣·北河二」以外的1只「星圣」怪兽特殊召唤。这个回合，自己不是光·暗属性怪兽不能从额外卡组特殊召唤。 ②：有这张卡在作为超量素材中的「星圣」超量怪兽得到以下效果。 ●1回合1次，对方把魔法卡的效果发动时才能发动。自己场上2个超量素材取除，那个效果无效并破坏。'),
(47579719, 'Constellar Hyades', '星圣·毕星团', 'セイクリッド・ヒアデス', 'XYZ Monster', 'Beast-Warrior', 'LIGHT', 3, 1900, 1100, '光属性3星怪兽×2 1回合1次，把这张卡1个超量素材取除才能发动。对方场上存在的怪兽全部变成表侧守备表示。'),
(70908596, 'Constellar Kaus', '星圣 射手考斯特', 'セイクリッド・カウスト', 'Effect Monster', 'Beast-Warrior', 'LIGHT', 4, 1800, 700, '这张卡不能作为同调素材。 ①：可以以场上1只「星圣」怪兽为对象从以下效果选择1个发动。这个效果1回合可以使用最多2次。 ●作为对象的怪兽的等级上升1星。 ●作为对象的怪兽的等级下降1星。'),
(17129783, 'Constellar Leonis', '星圣·轩辕十四', 'セイクリッド・レオニス', 'Effect Monster', 'Beast', 'LIGHT', 3, 1000, 1800, '只要这张卡在场上表侧表示存在，自己的主要阶段时只有1次，自己在通常召唤外加上可以把1只名字带有「星圣」的怪兽召唤。'),
(63545861, 'Constellar Meteor', '星圣的流星', 'セイクリッドの流星', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这张卡发动的回合，和名字带有「星圣」的怪兽进行战斗没被战斗破坏的对方怪兽在伤害步骤结束时回到持有者卡组。'),
(26329679, 'Constellar Omega', '星圣 欧米伽星团', 'セイクリッド・オメガ', 'XYZ Monster', 'Beast-Warrior', 'LIGHT', 4, 2400, 500, '光属性4星怪兽×2 ①：自己·对方回合1次，把这张卡1个超量素材取除才能发动。自己场上的全部「星圣」怪兽直到回合结束时不受魔法·陷阱卡的效果影响。'),
(73964868, 'Constellar Pleiades', '星圣 昴星团', 'セイクリッド・プレアデス', 'XYZ Monster', 'Warrior', 'LIGHT', 5, 2500, 1500, '光属性5星怪兽×2 ①：自己·对方回合1次，把这张卡1个超量素材取除，以场上1张卡为对象才能发动。那张卡回到手卡。'),
(78364470, 'Constellar Pollux', '星圣 双子波鲁克斯', 'セイクリッド・ポルクス', 'Effect Monster', 'Warrior', 'LIGHT', 4, 1700, 600, '①：这张卡召唤成功的回合，自己在通常召唤外加上只有1次，自己主要阶段可以把1只「星圣」怪兽召唤。'),
(2091298, 'Constellar Praesepe', '星圣 蜂巢星团', 'セイクリッド・ビーハイブ', 'XYZ Monster', 'Machine', 'LIGHT', 4, 2400, 800, '4星「星圣」怪兽×2 ①：1回合1次，自己的「星圣」怪兽进行战斗的从伤害步骤开始时到伤害计算前，把这张卡1个超量素材取除才能发动。那只怪兽的攻击力直到回合结束时上升1000。这个效果在对方回合也能发动。'),
(38495396, 'Constellar Ptolemy M7', '星圣 托勒密星团M7', 'セイクリッド・トレミスM７', 'XYZ Monster', 'Machine', 'LIGHT', 6, 2700, 2000, '6星怪兽×2 这张卡也能在「星圣神龙 托勒密星团M7」以外的自己场上的「星圣」超量怪兽上面重叠来超量召唤。这个方法特殊召唤的回合，这张卡的①的效果不能发动。 ①：1回合1次，把这张卡1个超量素材取除，以自己或对方的场上·墓地1只怪兽为对象才能发动。那只怪兽回到手卡。'),
(70624184, 'Constellar Rasalhague', '星圣·候', 'セイクリッド・ハワー', 'Effect Monster', 'Spellcaster', 'LIGHT', 2, 900, 100, '把这张卡解放才能发动。从自己的手卡·墓地把「星圣·候」以外的1只名字带有「星圣」的怪兽表侧守备表示特殊召唤。'),
(78486968, 'Constellar Sheratan', '星圣·娄宿一', 'セイクリッド・シェラタン', 'Effect Monster', 'Beast', 'LIGHT', 3, 700, 1900, '①：这张卡召唤成功时才能发动。从卡组把1只「星圣」怪兽加入手卡。'),
(44635489, 'Constellar Siat', '星圣·羽林军二十六', 'セイクリッド・シェアト', 'Effect Monster', 'Fairy', 'LIGHT', 1, 100, 1600, '对方场上有怪兽存在，自己场上没有怪兽存在的场合，这张卡可以从手卡特殊召唤。此外，1回合1次，选择自己的场上·墓地1只名字带有「星圣」的怪兽才能发动。这张卡变成和选择的怪兽相同等级。把场上的这张卡作为超量素材的场合，不是名字带有「星圣」的怪兽的超量召唤不能使用。'),
(78358521, 'Constellar Sombre', '星圣 索恩布雷斯', 'セイクリッド・ソンブレス', 'Effect Monster', 'Fairy', 'LIGHT', 4, 1550, 1600, '「星圣·草帽星系」的①②③的效果1回合各能使用1次。 ①：把自己墓地1只「星圣」怪兽除外，以自己墓地1只「星圣」怪兽为对象才能发动。那只怪兽加入手卡。 ②：这张卡的①的效果适用的回合的主要阶段才能发动。把1只「星圣」怪兽召唤。 ③：这张卡被送去墓地的回合，「星圣」怪兽召唤的场合需要的解放可以减少1只。'),
(35631584, 'Constellar Star Chart', '星圣的星痕', 'セイクリッドの星痕', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '自己场上有名字带有「星圣」的超量怪兽特殊召唤时，可以从自己卡组抽1张卡。这个效果1回合只能使用1次。'),
(90156158, 'Constellar Star Cradle', '星圣的超新生', 'セイクリッドの超新生', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '选择自己墓地2只名字带有「星圣」的怪兽加入手卡。这张卡发动的回合，自己不能进行战斗阶段。'),
(10125011, 'Constellar Tellarknights', '星圣的守星骑士团', '星守の騎士団', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张，这个卡名的②的效果1回合只能使用1次。 ①：作为这张卡的发动时的效果处理，可以从自己的手卡·墓地把1只「星骑士」、「星圣」怪兽特殊召唤。 ②：以自己场上1只「星骑士」、「星圣」超量怪兽为对象才能发动。和那只自己怪兽阶级不同的1只「星骑士」、「星圣」超量怪兽在作为对象的怪兽上面重叠当作超量召唤从额外卡组特殊召唤。'),
(4820694, 'Constellar Tempest', '星圣暴风', 'セイクリッド・テンペスト', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '「星圣暴风」的①的效果在决斗中只能使用1次。 ①：自己结束阶段以自己场上2只持有超量素材的「星圣」超量怪兽为对象才能发动。那2只超量怪兽的超量素材全部取除，对方基本分变成一半。 ②：自己准备阶段以自己场上1只「星圣」超量怪兽和自己墓地1只「星圣」怪兽为对象才能发动。那只墓地的怪兽在那只超量怪兽下面重叠作为超量素材。'),
(35544402, 'Constellar Twinkle', '闪烁星圣', 'ティンクル・セイクリッド', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '「闪烁星圣」的②的效果1回合只能使用1次。 ①：以自己场上1只「星圣」怪兽为对象才能发动。那只怪兽的等级上升1星或者2星。 ②：这张卡在墓地存在的场合，把自己墓地1只「星圣」怪兽除外才能发动。墓地的这张卡加入手卡。'),
(40143123, 'Constellar Virgo', '星圣·角宿一', 'セイクリッド・スピカ', 'Effect Monster', 'Fairy', 'LIGHT', 5, 2300, 1600, '这张卡召唤成功时，可以从手卡把1只名字带有「星圣」的5星怪兽表侧守备表示特殊召唤。'),
(14759024, 'Constellar Zubeneschamali', '星圣·氐宿四', 'セイクリッド・エスカ', 'Effect Monster', 'Machine', 'LIGHT', 5, 2100, 1400, '这张卡召唤·特殊召唤成功时，可以从自己卡组把1只名字带有「星圣」的怪兽加入手卡。'),
(34475451, 'Construction Train Signal Red', '工程列车 红色信号', '工作列車シグナル・レッド', 'Effect Monster', 'Machine', 'EARTH', 3, 1000, 1300, '①：对方怪兽的攻击宣言时才能发动。这张卡从手卡特殊召唤，那只对方怪兽的攻击对象转移为这张卡进行伤害计算。这张卡不会被那次战斗破坏。'),
(300302025, 'Consumed By Darkness', NULL, NULL, 'Skill Card', 'Yubel', NULL, NULL, NULL, NULL, NULL),
(16616620, 'Contact', '接触', 'コンタクト', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '把自己场上名字带有「茧状体」的怪兽全部送去墓地，那些卡记述的1只怪兽从手卡·卡组特殊召唤。'),
(87170768, 'Contact "C"', '接触的G', '接触するG', 'Effect Monster', 'Insect', 'EARTH', 6, 1500, 2200, '①：对方对怪兽的召唤·特殊召唤成功时才能发动。这张卡从手卡往对方场上守备表示特殊召唤。 ②：只要这张卡在怪兽区域存在，这张卡的控制者进行融合·同调·超量·连接召唤的场合，不是以这张卡为素材的融合·同调·超量·连接召唤不能进行。'),
(41933425, 'Contact Gate', '接触之门', 'コンタクト・ゲート', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从自己墓地把「新空间侠」怪兽2种类各1只除外才能发动。从自己的手卡·卡组·墓地选2只「新空间侠」怪兽特殊召唤（同名卡最多1张）。这个效果发动过的回合，自己不是融合怪兽不能从额外卡组特殊召唤。 ②：自己场上的表侧表示的需以「元素英雄 新宇侠」为融合素材的融合怪兽回到额外卡组的场合，把墓地的这张卡除外才能发动。选除外的1只自己的「新空间侠」怪兽特殊召唤。'),
(69270537, 'Contact Out', '接触分离', 'コンタクト・アウト', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '自己场上表侧表示存在的1只名字带有「新宇」的融合怪兽回到融合卡组。若回到融合卡组的怪兽记述的一组融合素材怪兽在自己卡组齐集，可以再把这一组在自己场上特殊召唤。'),
(83544697, 'Contact with Gusto', '薰风的交信', 'ガスタの交信', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '选择自己墓地存在的2只名字带有「薰风」的怪兽，加入卡组洗切。那之后，选择对方场上存在的1张卡破坏。'),
(10925955, 'Contact with the Aquamirror', '与仪水镜之交讯', '儀水鏡との交信', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上有水属性怪兽表侧表示存在的场合，从以下效果选择1个发动。自己场上有水属性的仪式怪兽表侧表示存在的场合，可以选择两方发动。 ●对方的魔法与陷阱卡区域盖放的卡全部确认再回到原状。 ●从自己或者对方的卡组上面把2张卡确认，用喜欢的顺序回到卡组上面。'),
(62777823, 'CONTAIN!', '遏制！', 'CONTAIN！', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名在规则上也当作「救援ACE队」卡使用。 ①：自己场上有「救援ACE队」怪兽存在的场合，以对方场上1只效果怪兽为对象才能发动。这个回合，那只效果怪兽不能攻击，效果无效化。自己场上有「救援ACE队 消防栓」存在的场合，再在这个回合让作为对象的怪兽不能作为融合·同调·超量·连接召唤的素材。'),
(68057622, 'Continuous Destruction Punch', '反击机枪拳', 'カウンターマシンガンパンチ', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '若被攻击的守备怪兽的守备力比对方攻击怪兽的攻击力高，则这只攻击怪兽被破坏。'),
(46259438, 'Contract Laundering', '契约洗净', '契約洗浄', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己的魔法与陷阱区域的「契约书」卡全部破坏。自己从卡组抽出破坏的数量。那之后，自己回复抽出数量×1000基本分。'),
(56673480, 'Contract with Don Thousand', '上千主上的契约', 'ドン・サウザンドの契約', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '「上千主上的契约」在1回合只能发动1张。 ①：作为这张卡的发动时的效果处理，双方玩家失去1000基本分，各自从卡组抽1张。 ②：双方玩家把这张卡在魔法与陷阱区域存在期间抽到的卡以及这张卡的①的效果抽到的卡持续公开。 ③：这张卡的效果让手卡的魔法卡公开中的玩家不能把怪兽通常召唤。'),
(33244944, 'Contract with Exodia', '与艾克佐迪亚的契约', 'エクゾディアとの契約', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己墓地有「被封印的艾克佐迪亚」「被封印者的右腕」「被封印者的左腕」「被封印者的右足」「被封印者的左足」存在的场合才能发动。从手卡把1只「艾克佐迪亚的亡灵」特殊召唤。'),
(69035382, 'Contract with the Abyss', '与奈落的契约', '奈落との契約', 'Spell Card', 'Ritual', NULL, NULL, NULL, NULL, '暗属性仪式怪兽的降临必需。 ①：等级合计直到变成和仪式召唤的怪兽相同为止，把自己的手卡·场上的怪兽解放，从手卡把1只暗属性仪式怪兽仪式召唤。'),
(96420087, 'Contract with the Dark Master', '与暗之支配者的契约', '闇の支配者との契約', 'Spell Card', 'Ritual', NULL, NULL, NULL, NULL, '「暗之支配者-佐克」的降临必需。 ①：从自己的手卡·场上把等级合计直到8以上的怪兽解放，从手卡把「暗之支配者-佐克」仪式召唤。'),
(19828680, 'Contract with the Void', '炼狱的契约', '煉獄の契約', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：这张卡以外的自己手卡是3张以上的场合才能发动。自己手卡全部丢弃。那之后，可以从自己墓地选1只「永火」怪兽或者龙族·暗属性·8星的同调怪兽特殊召唤。'),
(23204029, 'Contrast HERO Chaos', '对极－英雄 混沌', 'C・HERO カオス', 'Fusion Monster', 'Warrior', 'DARK', 9, 3000, 2600, '「假面英雄」怪兽×2 这个卡名在规则上也当作「元素英雄」卡使用。这张卡不用融合召唤不能特殊召唤。 ①：只要这张卡在怪兽区域存在，这张卡的属性也当作「光」使用。 ②：自己·对方回合1次，以场上1张表侧表示卡为对象才能发动。那张卡的效果直到回合结束时无效。'),
(291414, 'Converging Wills Dragon', '聚集思念之龙', '想い集いし竜', 'Tuner Monster', 'Dragon', 'LIGHT', 1, NULL, NULL, '自己对「集心龙」1回合只能有1次特殊召唤，把这张卡作为同调素材的场合，不是「救世」怪兽的同调召唤不能使用。 ①：这张卡的卡名只要在场上·墓地存在当作「救世龙」使用。 ②：把这张卡抽到时，把这张卡给对方观看才能发动。这张卡从手卡特殊召唤。自己场上有8星以上的龙族同调怪兽存在的场合，可以再从卡组把1只龙族·1星怪兽特殊召唤。'),
(20007374, 'Converging Wishes', '聚集之祈愿', '集いし願い', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己墓地有龙族同调怪兽5种类以上存在的场合才能发动。从额外卡组把1只「星尘龙」当作同调召唤作特殊召唤，把这张卡装备。这个效果特殊召唤的怪兽在结束阶段除外。 ②：装备怪兽的攻击力上升自己墓地的龙族同调怪兽的攻击力的合计数值。 ③：每次装备怪兽战斗破坏对方怪兽，把自己墓地1只龙族同调怪兽除外才能发动。装备怪兽向对方怪兽可以继续攻击。'),
(82639107, 'Convert Contact', '转换接触', 'コンバート・コンタクト', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己场上没有怪兽存在的场合才能发动。从手卡以及卡组把「新空间侠」卡各1张送去墓地。那之后，自己从卡组抽2张。'),
(43471513, 'Convex Knight', NULL, NULL, 'Effect Monster', 'Machine', 'EARTH', 4, 1800, 500, NULL),
(62966332, 'Convulsion of Nature', '天变地异', '天変地異', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '只要这张卡在场上存在，双方玩家把卡组上下翻转过来进行决斗。'),
(67098897, 'Cooky★Yummy Way', '曲奇喵★黯蜜味', 'クッキィ★ヤミーウェイ', 'Synchro Tuner Monster', 'Beast', 'LIGHT', 2, 1600, NULL, '调整＋调整以外的怪兽1只 这张卡同调召唤的场合，可以把自己场上1只连接1怪兽当作1星调整使用。这个卡名的①②的效果1回合各能使用1次。 ①：这张卡同调召唤的场合，以场上最多2只表侧表示怪兽为对象才能发动。那些怪兽变成里侧守备表示。 ②：对方把魔法·陷阱·怪兽的效果发动时，让这张卡回到额外卡组才能发动。从自己墓地把最多2只「味美喵」怪兽特殊召唤。'),
(68810435, 'Cooky☆Yummy', '曲奇喵☆黯蜜', 'クッキィ☆ヤミー', 'Effect Monster', 'Beast', 'LIGHT', 1, 1000, NULL, '这个卡名的①的方法的特殊召唤1回合只能有1次，②的效果1回合只能使用1次。 ①：连接1怪兽或者2星同调怪兽在自己场上存在的场合，这张卡可以从手卡特殊召唤。 ②：这张卡召唤·特殊召唤的场合，以对方场上1只表侧表示怪兽为对象才能发动。那只怪兽的攻击力下降1000。同调怪兽的效果特殊召唤的场合，也能作为代替把作为对象的怪兽破坏。'),
(83819309, 'Cooling Embers', '冷却之火', '冷える火', 'Effect Monster', 'Pyro', 'FIRE', 3, 500, 1500, '①：自己或对方的基本分回复的场合才能发动。这张卡从手卡特殊召唤。 ②：1回合1次，这张卡在怪兽区域存在的状态，自己或对方的基本分回复的场合才能发动。自己或对方的基本分回复1000。'),
(70219023, 'Coordius the Triphasic Dealmon', '三相魔神 科迪乌斯', '三相魔神コーディウス', 'Fusion Monster', 'Fiend', 'DARK', 9, 3000, 3000, '同调怪兽＋超量怪兽＋连接怪兽 这个卡名的效果1回合只能使用1次。 ①：只在融合召唤的这张卡在场上表侧表示存在才有1次，可以支付2000的倍数的基本分，从以下效果选择支付的基本分每2000为1个的数量发动。 ●从自己墓地选1张魔法·陷阱卡加入手卡。 ●选对方场上3张卡破坏。 ●这个回合，其他的自己怪兽不能攻击，这张卡的攻击力上升双方基本分差的一半数值。'),
(21843307, 'Copy Knight', '复制骑士', 'コピー・ナイト', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '自己场上有4星以下的战士族怪兽召唤时才能发动。这张卡发动后变成和那只召唤的怪兽相同等级的同名怪兽卡（战士族·光·攻/守0）在怪兽卡区域特殊召唤。这张卡也当作陷阱卡使用。'),
(66457407, 'Copy Plant', '复制植物', 'コピー・プラント', 'Tuner Monster', 'Plant', 'WIND', 1, NULL, NULL, '1回合1次，选择这张卡以外的场上1只植物族怪兽才能发动。这张卡的等级直到结束阶段时变成和选择的怪兽相同等级。'),
(26376390, 'Copycat', '模仿的幻想师', 'ものマネ幻想師', 'Effect Monster', 'Spellcaster', 'LIGHT', 1, NULL, NULL, '这张卡召唤·反转召唤·特殊召唤成功时，选择对方场上表侧表示存在的1只怪兽发动。这张卡的攻击力·守备力变成和选择的怪兽的原本的攻击力·守备力相同数值。'),
(42566602, 'Coral Dragon', '瑚之龙', '瑚之龍', 'Synchro Tuner Monster', 'Dragon', 'WATER', 6, 2400, 500, '调整＋调整以外的怪兽1只以上 这个卡名的②的效果1回合只能使用1次。 ①：1回合1次，丢弃1张手卡，以对方场上1张卡为对象才能发动。那张卡破坏。 ②：同调召唤的这张卡被送去墓地的场合才能发动。自己从卡组抽1张。'),
(18517177, 'Core Blast', '核心爆破', 'コア・ブラスト', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '自己的准备阶段时只有1次，对方场上存在的怪兽数量比自己多的场合，可以直到变成和自己场上存在的怪兽数量相同数量为止把对方场上存在的卡破坏。这个效果在自己场上有名字带有「核成」的怪兽表侧表示存在的场合才能发动。'),
(59385322, 'Core Blaster', '核心破坏炮', 'コアバスター', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '名字带有「核成」的怪兽才能装备。装备怪兽和光属性或者暗属性怪兽进行战斗的场合，不进行伤害计算把那只怪兽破坏。装备怪兽从场上离开让这张卡被送去墓地时，这张卡可以回到手卡。'),
(13997673, 'Core Compression', '核心浓度压缩', 'コア濃度圧縮', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '把手卡1张「核成兽的钢核」给对方观看，从手卡丢弃1只名字带有「核成」的怪兽发动。从自己卡组抽2张卡。'),
(3806388, 'Core of Chaos', '混沌核', '混沌核', 'Tuner Monster', 'Thunder', 'LIGHT', 2, NULL, 1600, '这张卡不能通常召唤，用卡的效果才能特殊召唤。这个卡名的①②的效果1回合各能使用1次。 ①：从自己的手卡·墓地把1只暗属性怪兽除外才能发动。这张卡从手卡特殊召唤。这个回合，自己不是光·暗属性的同调怪兽不能从额外卡组特殊召唤。 ②：这张卡特殊召唤成功的场合，以除外的1只自己的「混沌壳」为对象才能发动。那只怪兽特殊召唤。 ③：表侧表示的这张卡从场上离开的场合除外。'),
(36560997, 'Core Overclock', '超越核心界限', 'オーバー・コアリミット', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '只要这张卡在场上存在，自己场上表侧表示存在的名字带有「核成」的全部怪兽的攻击力上升500。此外，1回合1次，自己的主要阶段时可以从手卡丢弃1张「核成兽的钢核」，自己场上表侧表示存在的名字带有「核成」的全部怪兽的攻击力直到结束阶段时上升1000。'),
(8057630, 'Core Reinforcement', '核心再炼成', 'コアの再練成', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '选择自己墓地存在的1只名字带有「核成」的怪兽，攻击表示特殊召唤。自己的结束阶段时那只怪兽被破坏时，这张卡的控制者受到那只怪兽的攻击力数值的伤害。这张卡不在场上存在时，那只怪兽破坏。那只怪兽破坏时这张卡破坏。'),
(30770156, 'Core Transport Unit', '核心传送装置', 'コア転送ユニット', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '1回合1次，可以丢弃1张手卡，从自己卡组把1张「核成兽的钢核」加入手卡。'),
(92565383, 'Cornfield Coatl', '玉米田 科亚特尔', 'コーンフィールド コアトル', 'Effect Monster', 'Illusion', 'WIND', 4, 500, 1700, '这个卡名的①③的效果1回合各能使用1次。 ①：把这张卡从手卡丢弃才能发动。把「玉米田蛇神」以外的有「合成兽融合」的卡名记述的1只怪兽从卡组加入手卡。 ②：这张卡和怪兽进行战斗的场合，那2只不会被那次战斗破坏。 ③：自己场上有「有翼幻兽 奇美拉」存在，自己场上的卡为对象的效果由对方发动时，把场上·墓地的这张卡除外才能发动。那个效果无效并破坏。'),
(26257572, 'Corridor of Agony', '苦痛的回廊', '苦痛の回廊', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '只要这张卡在场上存在，从卡组特殊召唤的怪兽只要在场上表侧表示存在效果不能发动并无效化，也不能攻击宣言。'),
(34290067, 'Corroding Shark', '死亡鲨', 'デッド・シャーク', 'Normal Monster', 'Zombie', 'DARK', 3, 1100, 700, '在海里彷徨的鲨鱼，遇上它的人都会被施与诅咒。'),
(13235258, 'Corrosive Scales', '侵蚀鳞粉', '蝕みの鱗粉', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：以自己场上1只昆虫族怪兽为对象才能把这张卡发动。这张卡当作装备卡使用给那只怪兽装备。对方不能向那只自己的装备怪兽以外的昆虫族怪兽攻击。 ②：只要这张卡装备中，每次对方把怪兽召唤·特殊召唤或者每次对方把魔法·陷阱·怪兽的效果发动，给对方场上的表侧表示怪兽全部各放置1个鳞粉指示物。对方场上的怪兽的攻击力·守备力下降那怪兽的鳞粉指示物数量×100。'),
(67949763, 'Corrupted Keys', '罪键之法', '罪鍵の法－シン・キー・ロウ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '选择自己场上1只超量怪兽才能发动。把3只「阴影蜃景衍生物」（恶魔族·暗·1星·攻?/守0）特殊召唤。这衍生物的攻击力变成和选择的怪兽的攻击力相同。这衍生物不能直接攻击，不能为上级召唤以外而解放。选择的怪兽从场上离开时，这个效果特殊召唤的衍生物全部破坏。'),
(2561846, 'Corruption Cell "A"', '侵食细胞「A」', '侵食細胞「A」', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '对方场上表侧表示存在的1只怪兽放置1个A指示物。'),
(21123811, 'Cosmic Blazar Dragon', '宇宙耀变龙', 'コズミック・ブレイザー・ドラゴン', 'Synchro Monster', 'Dragon', 'WIND', 12, 4000, 4000, '同调怪兽调整＋调整以外的同调怪兽2只以上 这张卡不用同调召唤不能特殊召唤。 ①：可以把场上的这张卡直到结束阶段除外，从以下效果选择1个发动。 ●对方把魔法·陷阱·怪兽的效果发动时才能发动。那个发动无效并破坏。 ●对方把怪兽召唤·反转召唤·特殊召唤之际才能发动。那个无效，那些怪兽破坏。 ●对方怪兽的攻击宣言时才能发动。那次攻击无效，那之后战斗阶段结束。'),
(27450400, 'Cosmic Compass', '密集钟摆', 'クラスター・ペンデュラム', 'Effect Monster', 'Machine', 'EARTH', 1, 100, 300, '①：这张卡召唤成功时才能发动。把最多有对方场上的怪兽数量的「钟摆衍生物」（机械族·地·1星·攻/守0）在自己场上特殊召唤。'),
(8267140, 'Cosmic Cyclone', '宇宙气旋', 'コズミック・サイクロン', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：支付1000基本分，以场上1张魔法·陷阱卡为对象才能发动。那张卡除外。'),
(84012625, 'Cosmic Flare', '流星音击', 'シューティング・ソニック', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：以自己场上1只「星尘」同调怪兽为对象才能发动。这个回合，那只自己的同调怪兽和对方怪兽进行战斗的场合，伤害步骤开始时那只对方怪兽回到持有者卡组。 ②：自己场上的「星尘」同调怪兽为让效果发动而把自身解放的场合，可以作为代替把墓地的这张卡除外。'),
(68319538, 'Cosmic Fortress Gol''gar', '宇宙城 哥尔加', '宇宙砦ゴルガー', 'Synchro Monster', 'Reptile', 'LIGHT', 5, 2600, 1800, '「外星菊石」＋调整以外的「外星」怪兽1只以上 ①：1回合1次，以场上的表侧表示的魔法·陷阱卡任意数量为对象才能发动。那些表侧表示的卡回到持有者手卡。那之后，回到手卡的数量的A指示物给场上的表侧表示怪兽放置。 ②：1回合1次，把场上2个A指示物取除，以对方场上1张卡为对象才能发动。那张对方的卡破坏。'),
(51192573, 'Cosmic Horror Gangi''el', '宇宙兽 冈吉尔', '宇宙獣ガンギル', 'Effect Monster', 'Reptile', 'LIGHT', 7, 2600, 2000, '把自己场上存在的原本持有者是对方的怪兽作为祭品的场合，这张卡可以用1只祭品作召唤。1回合1次，可以在对方场上1只怪兽放置1个A指示物。放置有A指示物的怪兽和名字带有「外星」的怪兽战斗的场合，每有1个A指示物攻击力·守备力下降300。'),
(37442336, 'Cosmic Quasar Dragon', '宇宙类星龙', 'コズミック・クェーサー・ドラゴン', 'Synchro Monster', 'Dragon', 'LIGHT', 12, 4000, 4000, '同调怪兽调整＋调整以外的同调怪兽2只以上 这张卡用以上记的卡为同调素材的同调召唤才能从额外卡组特殊召唤。 ①：1回合1次，以最多有作为这张卡的同调素材的怪兽数量＋1张的场上的表侧表示卡为对象才能发动（这个效果的发动和效果不会被无效化）。那些卡的效果无效。 ②：自己·对方回合，把同调召唤的这张卡除外才能发动。以调整以外的同调怪兽2只以上为素材的1只龙族同调怪兽当作同调召唤从额外卡组特殊召唤。'),
(1487805, 'Cosmic Slicer Zer''oll', '宇宙铗 泽罗奥尔', '宇宙鋏ゼロオル', 'Link Monster', 'Reptile', 'LIGHT', NULL, 2600, NULL, '爬虫类族怪兽2只以上 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡连接召唤成功的场合才能发动。把持有把A指示物放置效果的1张卡从卡组加入手卡。 ②：把自己·对方场上2个A指示物取除才能发动。把1只爬虫类族怪兽召唤。 ③：只要这张卡在怪兽区域存在，有A指示物放置的对方怪兽变成守备表示，不能把效果发动。'),
(74139959, 'Cosmic Tree Irmistil', '星界树 伊尔米斯特尔', '星界樹イルミスティル', 'Link Monster', 'Plant', 'EARTH', NULL, 2000, NULL, '效果怪兽3只以上 ①：「星界树 伊尔明耀星树」在自己场上只能有1张表侧表示存在。 ②：只要这张卡在怪兽区域存在，每次对方在主要阶段把怪兽表侧表示特殊召唤，自己回复那些怪兽的攻击力数值的基本分。 ③：自己·对方回合1次，支付1000的倍数的基本分才能发动（最多3000）。这张卡的攻击力上升支付的数值。'),
(85679527, 'Cosmo Brain', '宇宙智囊', 'コスモブレイン', 'Effect Monster', 'Spellcaster', 'DARK', 7, 1500, 2450, '这张卡不能通常召唤。从手卡以及自己场上的表侧表示怪兽之中把效果怪兽以外的1只怪兽送去墓地的场合可以特殊召唤。这个卡名的②的效果1回合只能使用1次。 ①：这张卡的攻击力上升因为这张卡特殊召唤而送去墓地的怪兽的等级×200。 ②：把自己场上1只效果怪兽解放才能发动。从手卡·卡组把1只通常怪兽特殊召唤。'),
(38999506, 'Cosmo Queen', '宇宙女皇', 'コスモクイーン', 'Normal Monster', 'Spellcaster', 'DARK', 8, 2900, 2450, '统治着宇宙中存在的所有星球的女王。'),
(85314178, 'Cosmo Queen the Queen of Prayers', '祈祷的女王－宇宙女皇', '祈りの女王－コスモクイーン', 'Effect Monster', 'Spellcaster', 'DARK', 8, 2900, 2450, '这个卡名的①②的效果1回合各能使用1次。 ①：场地魔法卡发动的场合才能发动。这张卡从手卡守备表示特殊召唤。 ②：可以以场地区域1张表侧表示卡为对象，那个控制者对应的以下效果发动。 ●自己：作为对象的卡破坏，和破坏的卡卡名不同的1张场地魔法卡从卡组加入手卡。 ●对方：作为对象的卡的效果直到回合结束时无效，从卡组把1张场地魔法卡加入手卡。'),
(91654806, 'Cosmos Channelling', '与宇宙的交信', '宇宙との交信', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：把原本持有者是对方的自己场上1只怪兽送去墓地才能发动。从自己的手卡·墓地选1只机械族怪兽特殊召唤。 ②：自己场上有「人造人-念力震慑者」存在，对方抽卡阶段对方通常抽卡时，宣言卡的种类（怪兽·魔法·陷阱）才能发动。抽到的卡给双方确认，宣言的种类的场合，这张卡送去墓地，自己从卡组抽1张。'),
(23265313, 'Cost Down', '代价降低', 'コストダウン', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：丢弃1张手卡才能发动。这个回合，自己手卡的怪兽的等级下降2星。'),
(5519829, 'Counselor Lily', '心理咨询师 莉莉', 'メンタル・カウンセラー リリー', 'Tuner Monster', 'Fairy', 'EARTH', 3, 400, 1500, '这张卡被同调怪兽的同调召唤使用送去墓地的场合，可以支付500基本分让这张卡为同调素材的同调怪兽的攻击力直到这个回合的结束阶段时上升1000。'),
(38834303, 'Counter Cleaner', '指示物吸除器', 'カウンタークリーナー', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '支付500基本分。场上存在的全部指示物取除。'),
(42309337, 'Counter Counter', '反击反击', 'カウンター・カウンター', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '反击陷阱卡的发动无效并破坏。'),
(94561645, 'Counter Gate', '反击之门', 'カウンター・ゲート', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：对方怪兽的直接攻击宣言时才能发动。那次攻击无效，自己从卡组抽1张。那张抽到的卡是怪兽的场合，可以把那只怪兽表侧攻击表示通常召唤。'),
(11136371, 'Counter Gem', '反击宝石', 'カウンター・ジェム', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：把这张卡以外的自己的魔法与陷阱区域的卡全部送去墓地才能发动。从自己墓地把「宝玉兽」怪兽尽可能当作永续魔法卡使用在自己的魔法与陷阱区域表侧表示放置。这个回合的结束阶段让自己场上的「宝玉兽」卡全部破坏。'),
(30488793, 'Counterforce', '反弹力', '反発力', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '表侧攻击表示存在的怪兽为攻击对象的怪兽的攻击无效时才能发动。给与对方基本分那2只怪兽的攻击力差的数值的伤害。'),
(26259179, 'Couple of Aces', '交杯Ace', 'Couple of Aces', 'Effect Monster', 'Fairy', 'EARTH', 2, 100, 100, '这个卡名的①的效果1回合只能使用1次。 ①：这张卡在手卡存在的场合才能发动。进行1次投掷硬币。表的场合，这张卡在自己场上特殊召唤。里的场合，这张卡在对方场上特殊召唤。 ②：这张卡的①的效果特殊召唤成功的场合发动。自己从卡组抽2张。'),
(90276649, 'Couplet the Melodious Songstress', '幻奏歌姬 库蒲蕾', '幻奏の歌姫クープレ', 'Pendulum Effect Monster', 'Fairy', 'LIGHT', 5, 1200, 2000, '这个卡名的①②的怪兽效果1回合各能使用1次。 ①：这张卡用通常抽卡以外的方法加入手卡的场合，把这张卡给对方观看才能发动。从自己的手卡·墓地把1只4星以下的「幻奏」怪兽特殊召唤。 ②：这张卡在额外卡组表侧存在的状态，自己场上有「幻奏」融合怪兽特殊召唤的场合才能发动。这张卡在自己的灵摆区域放置。'),
(91479482, 'Courageous Crimson Chevalier Bradamante', '红恋之丽杰－布拉达曼特', '紅恋の麗傑－ブラダマンテ', 'Tuner Monster', 'Warrior', 'FIRE', 1, 500, 200, '这个卡名在规则上也当作「焰圣骑士」卡使用。这个卡名的①②的效果1回合各能使用1次。 ①：把这张卡从手卡丢弃，以自己场上1只战士族怪兽为对象才能发动。从卡组选1张那只怪兽可以装备的装备魔法卡给那只怪兽装备。 ②：没有装备卡装备的这张卡被和对方怪兽的战斗破坏送去墓地时才能发动。这张卡特殊召唤，那只对方场上的怪兽当作装备卡使用给这张卡装备。'),
(28340377, 'Court of Cards', '绘札的牵绊', '絵札の絆', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：自己场上没有「王后骑士」「卫兵骑士」「国王骑士」以外的怪兽存在的场合才能发动。从自己的手卡·墓地选「王后骑士」「卫兵骑士」「国王骑士」之内1只特殊召唤。 ②：从自己的手卡·墓地把「王后骑士」「卫兵骑士」「国王骑士」各最多1只除外才能发动。自己从卡组抽出除外的数量。'),
(24449083, 'Court of Justice', '正义法院', 'コート・オブ・ジャスティス', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①的效果1回合只能使用1次。 ①：自己主要阶段才能发动。从手卡把1只天使族怪兽特殊召唤。这个效果在自己场上有1星天使族怪兽存在的场合才能发动和处理。'),
(74458486, 'Covering Fire', '援护射击', '援護射撃', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '对方怪兽攻击自己场上怪兽的场合，伤害步骤时发动。被攻击的自己怪兽的攻击力上升自己场上表侧表示存在的另外1只怪兽的攻击力的数值。'),
(91782219, 'Crab Turtle', '蟹龟', 'クラブ・タートル', 'Ritual Monster', 'Aqua', 'WATER', 8, 2550, 2500, '「龟的誓言」降临。必须从场地和手卡把等级直到8以上的卡作为祭品。'),
(36975314, 'Crackdown', '大搜捕', '大捕り物', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：以对方场上1只表侧表示怪兽为对象才能把这张卡发动。得到那只怪兽的控制权。那只怪兽在自己场上存在的场合，不能攻击，不能把效果发动。那只怪兽从场上离开时这张卡破坏。'),
(32835363, 'Cracking', '破解', 'クラッキング', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '场上存在的怪兽被卡的效果送去墓地时，给与那些怪兽的原本持有者800分伤害。这个效果1回合只能使用1次。'),
(60349525, 'Cracking Dragon', '破解龙', 'クラッキング・ドラゴン', 'Effect Monster', 'Machine', 'DARK', 8, 3000, NULL, '①：这张卡不会被和持有这张卡的等级以下的等级的怪兽的战斗破坏。 ②：这张卡在怪兽区域存在，对方只把怪兽1只召唤·特殊召唤时才能发动。那只怪兽的攻击力直到回合结束时下降那个等级×200，给与对方下降数值的伤害。'),
(28637168, 'Crane Crane', '起重鹤', 'クレーンクレーン', 'Effect Monster', 'Winged Beast', 'EARTH', 3, 300, 900, '这个卡名的效果1回合只能使用1次。 ①：这张卡召唤成功时，以自己墓地1只3星怪兽为对象才能发动。那只怪兽特殊召唤。这个效果特殊召唤的怪兽的效果无效化。'),
(18828179, 'Cranium Fish', '母脑鱼', 'マザー・ブレイン', 'Effect Monster', 'Fish', 'WATER', 6, 2400, 1000, '这张卡可以把自己场上存在的1只「海洋怪鱼卫士」解放，从手卡特殊召唤。可以从手卡把1只水属性怪兽丢弃去墓地，场上盖放的1张卡破坏。'),
(69042950, 'Crashbug Road', '漏洞载入', 'バグ・ロード', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '双方可以把和自己场上表侧表示存在的1只4星以下的怪兽相同等级的1只怪兽从手卡特殊召唤。'),
(87526784, 'Crashbug X', '漏洞人X', 'バグマンX', 'Effect Monster', 'Fiend', 'DARK', 3, NULL, 2000, '这张卡召唤成功时，自己场上有「漏洞人Y」表侧表示存在的场合，可以从自己卡组把1只「漏洞人Z」特殊召唤。'),
(23915499, 'Crashbug Y', '漏洞人Y', 'バグマンY', 'Effect Monster', 'Fiend', 'DARK', 3, 1400, 1600, '这张卡召唤成功时，自己场上有「漏洞人Z」表侧表示存在的场合，可以从自己卡组把1只「漏洞人X」特殊召唤。'),
(50319138, 'Crashbug Z', '漏洞人Z', 'バグマンZ', 'Effect Monster', 'Fiend', 'DARK', 3, NULL, 1500, '这张卡召唤成功时，自己场上有「漏洞人X」表侧表示存在的场合，可以从自己卡组把1只「漏洞人Y」特殊召唤。'),
(93889755, 'Crass Clown', '杀人小丑', 'マーダーサーカス', 'Effect Monster', 'Fiend', 'DARK', 4, 1350, 1400, '这张卡的表示形式从守备表示变成攻击表示时，对方场上的1只怪兽回到持有者手卡。');